PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?hyponymWr
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    # Find "valore" and its sense
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?wr ] ;
          ontolex:sense ?sense .
    FILTER(STR(?wr) = "valore")

    # Find direct hyponyms of "valore" (more specific terms)
    # lexinfo:hypernym points FROM general TO specific
    ?sense lexinfo:hypernym ?hyponymSense .

    # Get the written form of each hyponym
    ?hyponymWord ontolex:sense ?hyponymSense ;
                 ontolex:canonicalForm [ ontolex:writtenRep ?hyponymWr ] .

    # Check whether this hyponym has sub-hyponyms of its own (leaf node check)
    # Using OPTIONAL + FILTER(!BOUND) since NOT EXISTS/MINUS are not supported
    OPTIONAL {
      ?hyponymSense lexinfo:hypernym ?subHyponymSense .
    }
    FILTER(!BOUND(?subHyponymSense))
  }
}
ORDER BY ?hyponymWr

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?italianWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  lila:hasPOS lila:adjective ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                 marl:hasPolarity ?polarity ;
                 marl:hasPolarityValue ?polarityValue .
  FILTER(xsd:float(?polarityValue) > 0.5)

  FILTER NOT EXISTS {
    ?emotionEntry ontolex:canonicalForm ?italianLemma .
    GRAPH <http://w3id.org/elita> {
      ?emotionEntry elita:HasEmotion ?emotion .
    }
  }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?italianWord ?dialect ?dialectWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord ;
                  lila:hasPOS lila:noun .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }
  FILTER(STRENDS(STR(?italianWord), "polo"))

  ?translationEntry ontolex:canonicalForm ?italianLemma ;
                    vartrans:translatableAs ?dialectEntry .
  ?dialectEntry ontolex:canonicalForm ?dialectLemma .
  ?dialectLemma ontolex:writtenRep ?dialectWord .

  {
    ?dialectLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> .
    BIND("Sicilian" AS ?dialect)
  } UNION {
    ?dialectLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> .
    BIND("Parmigiano" AS ?dialect)
  }
}
ORDER BY ?italianWord ?dialect

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT (COUNT(DISTINCT ?italianLemma) AS ?count)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  {
    # Branch 1: Associated with Sadness in ELIta
    ?emotionEntry ontolex:canonicalForm ?italianLemma .
    GRAPH <http://w3id.org/elita> {
      ?emotionEntry elita:HasEmotion elita:Tristezza .
    }
  }
  UNION
  {
    # Branch 2: Sentix polarity value below -0.8
    ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                   marl:hasPolarity ?polarity ;
                   marl:hasPolarityValue ?polarityValue .
    FILTER(?polarityValue < -0.8)
  }
}

PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?writtenRep ?definition
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    {
      # Branch 1: Parts (meronyms) of 'galletto'
      ?galletto ontolex:canonicalForm [ ontolex:writtenRep ?gallWr ] .
      FILTER(STR(?gallWr) = "galletto")
      ?galletto ontolex:sense ?gallSense .

      # partMeronym points FROM part TO whole, so ?partSense is a part of ?gallSense
      ?partSense lexinfo:partMeronym ?gallSense .

      ?word ontolex:sense ?partSense ;
            ontolex:canonicalForm [ ontolex:writtenRep ?writtenRep ] .
      OPTIONAL { ?partSense skos:definition ?definition }
    }
    UNION
    {
      # Branch 2: Words whose definition mentions 'galletto'
      ?word ontolex:canonicalForm [ ontolex:writtenRep ?writtenRep ] ;
            ontolex:sense ?sense .
      ?sense skos:definition ?definition .
      FILTER(REGEX(STR(?definition), "galletto", "i"))
    }
  }
}

PREFIX complit: <http://klab/lexicon/vocabulary/compl-it#>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?italianWord
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    {
      # Branch 1: Words whose sense has SIMPLE semantic type 'Fruit'
      ?word ontolex:sense ?sense .
      ?sense complit:hasSemanticType ?semanticType .
      FILTER(REGEX(STR(?semanticType), "Fruit", "i"))
    }
    UNION
    {
      # Branch 2: Hyponyms of 'frutto'
      ?seedWord ontolex:canonicalForm [ ontolex:writtenRep ?seedWr ] ;
                ontolex:sense ?seedSense .
      FILTER(STR(?seedWr) = "frutto")
      # lexinfo:hypernym points FROM general TO specific: ?seedSense -> ?hyponymSense
      ?seedSense lexinfo:hypernym ?hyponymSense .
      ?word ontolex:sense ?hyponymSense .
    }
    # Retrieve the written form for the matched word
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?italianWord ] .
  }
}
